void PingPongProcess() {
    event_t eventPing = AllocEventID<HardEvent::MTE3_MTE2>();
    event_t eventPong = AllocEventID<HardEvent::MTE3_MTE2>();

    // Init: preset both flags
    SetFlag<HardEvent::MTE3_MTE2>(eventPing);
    SetFlag<HardEvent::MTE3_MTE2>(eventPong);

    for (int i = 0; i < N; i++) {
        event_t eventId = (i % 2 == 0) ? eventPing : eventPong;
        WaitFlag<HardEvent::MTE3_MTE2>(eventId);  // Wait last iteration
        DataCopyPad(...);  // MTE2 operation
        SetFlag<HardEvent::MTE3_MTE2>(eventId);  // Prepare next
    }

    // Finalize: wait all flags
    WaitFlag<HardEvent::MTE3_MTE2>(eventPing);
    WaitFlag<HardEvent::MTE3_MTE2>(eventPong);
}
```

